### 3.2. `test/es-module/test-esm-concurrent-resolution.js` (New File)

```javascript
'use strict';

// Regression test for race condition in ESM specifier resolution.
// When multiple concurrent import() calls target the same specifier,
// the loader must deduplicate resolution and return the same module
// instance to all callers — not crash or return inconsistent state.
//
// Root cause: TOCTOU race in ESMLoader.resolve() where concurrent
// calls both miss the _resolveCache and initiate independent
// resolutions, corrupting the module map.
//
// Ref: upstream PR nodejs/node#26745 (merged 2019-03-27, commit 2cb0b09e38)

const common = require('../common');
common.skipIfInspectorDisabled();

const assert = require('assert');
const { describe, it } = require('node:test') || { describe: global.describe, it: global.it };

// Use a small fixture module that has a side-effect we can observe
// to verify module identity (all imports return the same instance).
const fixtureURL = new URL(
  '../fixtures/es-modules/resolve-counter.mjs',
  __filename
).href;

// Number of concurrent import() calls for the same specifier.
const CONCURRENCY = 50;

// Barrier: accumulate callbacks until we have CONCURRENCY, then release.
// This ensures all import() calls are initiated as close to simultaneously
// as possible, maximizing the window for the race to manifest.
class Barrier {
  constructor(count) {
    this._count = count;
    this._resolve = null;
    this._promise = new Promise((resolve) => {
      this._resolve = resolve;
    });
    this._waiting = 0;
  }

  async wait() {
    this._waiting++;
    if (this._waiting >= this._count) {
      this._resolve();
    }
    return this._promise;
  }
}

async function testConcurrentResolution() {
  const barrier = new Barrier(CONCURRENCY);

  // Spawn CONCURRENCY import() calls, all gated behind the barrier
  // so they fire as close to simultaneously as possible.
  const promises = Array.from({ length: CONCURRENCY }, async (_, i) => {
    await barrier.wait();
    return import(fixtureURL);
  });

  const results = await Promise.all(promises);

  // All imports must resolve successfully
  assert.strictEqual(results.length, CONCURRENCY,
    `Expected ${CONCURRENCY} results, got ${results.length}`);

  // All imports must return the exact same module instance
  // (the module identity guarantee: same URL → same Module object)
  const first = results[0];
  for (let i = 1; i < results.length; i++) {
    assert.strictEqual(results[i], first,
      `Module identity violated: result[${i}] !== result[0]`);
  }

  // Verify the side-effect counter: the module's init code should
  // have executed exactly once, regardless of concurrent requests.
  // (The fixture increments a global counter on each evaluation.)
  const globalKey = '__resolveCounter_test_esm_concurrent';
  const evalCount = globalThis[globalKey] || 0;
  assert.strictEqual(evalCount, 1,
    `Module evaluated ${evalCount} times, expected exactly 1`);
}

async function testDifferentSpecifiersNoInterference() {
  // Negative case: concurrent import() for different specifiers
  // must not interfere with each other.
  const fixtureA = new URL(
    '../fixtures/es-modules/resolve-counter-a.mjs',
    __filename
  ).href;
  const fixtureB = new URL(
    '../fixtures/es-modules/resolve-counter-b.mjs',
    __filename
  ).href;

  const barrier = new Barrier(CONCURRENCY * 2);

  const promisesA = Array.from({ length: CONCURRENCY }, async () => {
    await barrier.wait();
    return import(fixtureA);
  });
  const promisesB = Array.from({ length: CONCURRENCY }, async () => {
    await barrier.wait();
    return import(fixtureB);
  });

  const [resultsA, resultsB] = await Promise.all([
    Promise.all(promisesA),
    Promise.all(promisesB),
  ]);

  // All A results are the same module
  for (let i = 1; i < resultsA.length; i++) {
    assert.strictEqual(resultsA[i], resultsA[0],
      'Module A identity violated across concurrent imports');
  }
  // All B results are the same module
  for (let i = 1; i < resultsB.length; i++) {
    assert.strictEqual(resultsB[i], resultsB[0],
      'Module B identity violated across concurrent imports');
  }
  // A and B are distinct modules
  assert.notStrictEqual(resultsA[0], resultsB[0],
    'Different specifiers must resolve to different modules');
}

async function testResolutionFailureCleanup() {
  // Edge case: a specifier that fails resolution must not leave
  // stale entries in the in-flight map that block future resolutions.
  const badSpecifier = '../fixtures/es-modules/nonexistent-module-xyz.mjs';
  const badURL = new URL(badSpecifier, __filename).href;

  // First attempt should reject
  await assert.rejects(
    () => import(badURL),
    { code: 'ERR_MODULE_NOT_FOUND' }
  );

  // Second attempt should also reject (not blocked by stale in-flight entry)
  await assert.rejects(
    () => import(badURL),
    { code: 'ERR_MODULE_NOT_FOUND' }
  );
}

// Run all sub-tests
async function main() {
  try {
    await testConcurrentResolution();
    console.log('ok 1 - concurrent resolution deduplication');
  } catch (err) {
    console.error('not ok 1 - concurrent resolution deduplication');
    console.error(err);
    process.exitCode = 1;
  }

  try {
    await testDifferentSpecifiersNoInterference();
    console.log('ok 2 - different specifiers do not interfere');
  } catch (err) {
    console.error('not ok 2 - different specifiers do not interfere');
    console.error(err);
    process.exitCode = 1;
  }

  try {
    await testResolutionFailureCleanup();
    console.log('ok 3 - resolution failure cleans up in-flight state');
  } catch (err) {
    console.error('not ok 3 - resolution failure cleans up in-flight state');
    console.error(err);
    process.exitCode = 1;
  }
}

main();
```

